25: function startOfDay(d: Date): number {
26:   return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime();
27: }
28: 
29: function sameDay(a: Date, b: Date): boolean {
30:   return startOfDay(a) === startOfDay(b);
31: }
