33: function formatDayLabel(iso: string): string {
34:   const d = new Date(iso);
35:   const now = new Date();
36:   if (sameDay(d, now)) {
37:     return 'сегодня';
38:   }
39:   const yesterday = new Date(now);
40:   yesterday.setDate(now.getDate() - 1);
41:   if (sameDay(d, yesterday)) {
42:     return 'вчера';
43:   }
44:   return `${d.getDate()} ${MONTHS_SHORT[d.getMonth()]}`;
45: }
