53:         prev.map((m) => (m.id === messageId ? { ...m, status } : m)),
54:       );
55:     },
56:     [],
57:   );
58: 
59:   useEffect(() => {
60:     let cancelled = false;
61: 
62:     (async () => {
63:       setLoading(true);
64:       try {
65:         const items = await listMessages(chatId);
66:         if (!cancelled) {
67:           setMessages(sortNewestFirst(items as ChatMessage[]));
